// Exact row-orbit verifier.  A canonical graph has sorted left-row masks.
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <optional>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem; using U64=std::uint64_t; using I64=std::int64_t; constexpr int MAX_N=11;
struct Cfg { std::string mode,out,shard,sha; int left=-1; U64 start=0,stop=0,every=1024; };
static std::string utc(){auto t=std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());std::tm z{};gmtime_r(&t,&z);std::ostringstream o;o<<std::put_time(&z,"%Y-%m-%dT%H:%M:%SZ");return o.str();}
static void put(const fs::path&p,const std::string&s){fs::create_directories(p.parent_path());auto q=fs::path(p.string()+".tmp");{std::ofstream f(q);if(!f)throw std::runtime_error("open output");f<<s<<'\n';}fs::rename(q,p);}
static Cfg parse(int ac,char**av){Cfg c;std::map<std::string,std::string*> ss{{"--mode",&c.mode},{"--out-dir",&c.out},{"--shard-id",&c.shard},{"--source-sha",&c.sha}};for(int i=1;i<ac;i+=2){if(i+1>=ac)throw std::runtime_error("missing option value");std::string k(av[i]),v(av[i+1]);if(auto it=ss.find(k);it!=ss.end())*it->second=v;else if(k=="--left-size")c.left=std::stoi(v);else if(k=="--start")c.start=std::stoull(v);else if(k=="--stop")c.stop=std::stoull(v);else if(k=="--checkpoint-every")c.every=std::stoull(v);else throw std::runtime_error("unknown option "+k);}if(c.mode.empty()||c.out.empty()||c.sha.empty())throw std::runtime_error("mode,out-dir,source-sha required");return c;}
static U64 binom(int n,int k){if(k<0||k>n)return 0;k=std::min(k,n-k);__uint128_t a=1;for(int i=1;i<=k;++i)a=a*static_cast<unsigned>(n-k+i)/static_cast<unsigned>(i);if(a>UINT64_MAX)throw std::runtime_error("binomial overflow");return static_cast<U64>(a);}
static U64 fact(int n){U64 x=1;for(int i=2;i<=n;++i)x*=i;return x;}
static std::vector<std::vector<int>> bysize(int n){std::vector<std::vector<int>>b(n+1);for(int x=0;x<(1<<n);++x)b[__builtin_popcount(static_cast<unsigned>(x))].push_back(x);return b;}
static std::vector<std::pair<int,int>> pairs(int n,int l){std::vector<std::pair<int,int>>e;for(int x=0;x<l;++x)for(int y=l;y<n;++y)e.emplace_back(x,y);return e;}
static std::vector<int> edgeadj(int n,const std::vector<std::pair<int,int>>&e,U64 mask){std::vector<int>a(n);for(size_t k=0;k<e.size();++k)if((mask>>k)&1){auto[x,y]=e[k];a[x]|=1<<y;a[y]|=1<<x;}return a;}
static std::vector<int> rowadj(int n,int l,const std::vector<int>&rows){std::vector<int>a(n);for(int x=0;x<l;++x)for(int j=0;j<n-l;++j)if((rows[x]>>j)&1){int y=l+j;a[x]|=1<<y;a[y]|=1<<x;}return a;}
// Frozen graph-level subset-DP recurrence.
static std::vector<U64> hist(const std::vector<int>&a,const std::vector<std::vector<int>>&bs){int n=a.size(),all=(1<<n)-1;std::vector<int>uni(1<<n);for(int m=1;m<=all;++m){int b=m&-m;uni[m]=uni[m^b]|a[__builtin_ctz(static_cast<unsigned>(b))];}std::vector<U64>h(n);for(int r=0;r<n;++r)for(int p=0;p<n;++p){if(r==p||(a[r]&(1<<p)))continue;int init=(1<<r)|(1<<p);std::vector<std::array<U64,MAX_N>>dp(1<<n);dp[init][0]=1;for(int rank=2;rank<n;++rank)for(int m:bs[rank]){auto row=dp[m];bool nz=false;for(int z=0;z<=n-2;++z)nz=nz||row[z];if(!nz)continue;int choices=uni[m]&~m&all;while(choices){int b=choices&-choices;choices^=b;int nm=m|b;bool pn=a[p]&b;for(int z=0;z<=n-2;++z)if(row[z])dp[nm][z?z:(pn?rank-1:0)]+=row[z];}}for(int z=1;z<=n-2;++z)h[z]+=dp[all][z];}return h;}
static std::vector<U64> direct(const std::vector<int>&a){int n=a.size();std::vector<int>w(n);std::iota(w.begin(),w.end(),0);std::vector<U64>h(n);do{int r=w[0],p=w[1];if(a[r]&(1<<p))continue;int seen=(1<<r)|(1<<p),z=0;bool ok=true;for(int pos=2;pos<n;++pos){int v=w[pos];if(!(a[v]&seen)){ok=false;break;}if(!z&&(a[p]&(1<<v)))z=pos-1;seen|=1<<v;}if(ok&&z)++h[z];}while(std::next_permutation(w.begin(),w.end()));return h;}
static I64 r45(const std::vector<U64>&h){return static_cast<I64>(h[3])-3*static_cast<I64>(h[4])+2*static_cast<I64>(h[5]);}
static I64 r27(const std::vector<U64>&h){return static_cast<I64>(h[2])-5*static_cast<I64>(h[4])+5*static_cast<I64>(h[6])-2*static_cast<I64>(h[7]);}
static I64 rj7(const std::vector<U64>&h){return static_cast<I64>(h[2])-7*static_cast<I64>(h[3])+21*static_cast<I64>(h[4])-35*static_cast<I64>(h[5])+35*static_cast<I64>(h[6])-21*static_cast<I64>(h[7])+7*static_cast<I64>(h[8])-2*static_cast<I64>(h[9]);}
static std::string arr(const std::vector<U64>&x){std::ostringstream o;o<<"[";for(size_t i=0;i<x.size();++i){if(i)o<<",";o<<x[i];}return o<<"]",o.str();}
static std::string rowsj(const std::vector<int>&x){std::ostringstream o;o<<"[";for(size_t i=0;i<x.size();++i){if(i)o<<",";o<<x[i];}return o<<"]",o.str();}
static void add(std::vector<U64>&x,const std::vector<U64>&y,U64 w){for(size_t i=0;i<x.size();++i){__uint128_t z=static_cast<__uint128_t>(x[i])+static_cast<__uint128_t>(w)*y[i];if(z>UINT64_MAX)throw std::runtime_error("checksum overflow");x[i]=static_cast<U64>(z);}}
// Rank/unrank: rows x_i nondecreasing in [0,m) map to strict y_i=x_i+i.
static std::vector<int> unrank(int m,int l,U64 rank){int n=m+l-1;if(rank>=binom(n,l))throw std::runtime_error("rank outside range");std::vector<int>x;int prev=-1;for(int pos=0;pos<l;++pos){bool hit=false;for(int y=prev+1;y<=n-(l-pos);++y){U64 block=binom(n-y-1,l-pos-1);if(rank<block){x.push_back(y-pos);prev=y;hit=true;break;}rank-=block;}if(!hit)throw std::runtime_error("unrank failed");}return x;}
static U64 weight(const std::vector<int>&x){U64 d=1;for(size_t i=0;i<x.size();){size_t j=i+1;while(j<x.size()&&x[j]==x[i])++j;d*=fact(static_cast<int>(j-i));i=j;}return fact(static_cast<int>(x.size()))/d;}
struct Sum{U64 graphs=0,items=0;std::vector<U64>h;};
static Sum labelled(int n,int l,I64(*rel)(const std::vector<U64>&)){auto e=pairs(n,l);auto bs=bysize(n);U64 tot=1ULL<<e.size();Sum s{0,0,std::vector<U64>(n)};for(U64 k=0;k<tot;++k){auto h=hist(edgeadj(n,e,k),bs);if(rel(h))throw std::runtime_error("nonzero relation in labelled scan");add(s.h,h,1);++s.graphs;++s.items;}return s;}
static Sum orbits(int n,int l,I64(*rel)(const std::vector<U64>&)){int m=1<<(n-l);U64 tot=binom(m+l-1,l);auto bs=bysize(n);Sum s{0,0,std::vector<U64>(n)};for(U64 k=0;k<tot;++k){auto x=unrank(m,l,k);U64 w=weight(x);auto h=hist(rowadj(n,l,x),bs);if(rel(h))throw std::runtime_error("nonzero relation in orbit scan");add(s.h,h,w);s.graphs+=w;++s.items;}return s;}
static void gate(const Cfg&c,int n,I64(*rel)(const std::vector<U64>&),const std::string&name){std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-roworbit-n"<<n<<"\",\"relation\":\""<<name<<"\",\"source_sha256\":\""<<c.sha<<"\",\"families\":[";bool first=true;U64 tg=0,to=0;for(int l=1;l<=n/2;++l){auto a=labelled(n,l,rel);auto b=orbits(n,l,rel);if(a.graphs!=b.graphs||a.h!=b.h)throw std::runtime_error("weighted checksum mismatch");if(!first)o<<",";first=false;o<<"{\"left_size\":"<<l<<",\"labeled_graphs\":"<<a.graphs<<",\"row_orbits\":"<<b.items<<",\"weighted_graphs\":"<<b.graphs<<",\"h_checksum\":"<<arr(b.h)<<",\"matches_labeled\":true}";tg+=a.graphs;to+=b.items;}o<<"],\"total_labeled_graphs\":"<<tg<<",\"total_row_orbits\":"<<to<<",\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/("gate-roworbit-n"+std::to_string(n)+".json"),o.str());}
static void gate_part(const Cfg&c,int n,int l,I64(*rel)(const std::vector<U64>&),const std::string&name){auto a=labelled(n,l,rel);auto b=orbits(n,l,rel);if(a.graphs!=b.graphs||a.h!=b.h)throw std::runtime_error("weighted checksum mismatch");std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-roworbit-n"<<n<<"-l"<<l<<"\",\"relation\":\""<<name<<"\",\"left_size\":"<<l<<",\"labeled_graphs\":"<<a.graphs<<",\"row_orbits\":"<<b.items<<",\"weighted_graphs\":"<<b.graphs<<",\"h_checksum\":"<<arr(b.h)<<",\"matches_labeled\":true,\"source_sha256\":\""<<c.sha<<"\",\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/("gate-roworbit-n"+std::to_string(n)+"-l"+std::to_string(l)+".json"),o.str());}
static void gate_transpose(const Cfg&c,int n,int small,int large,I64(*rel)(const std::vector<U64>&),const std::string&name){auto a=orbits(n,small,rel);auto b=orbits(n,large,rel);U64 want=1ULL<<(small*(n-small));if(a.graphs!=want||b.graphs!=want||a.h!=b.h)throw std::runtime_error("transpose weighted checksum mismatch");std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-transpose-n"<<n<<"\",\"relation\":\""<<name<<"\",\"original_small_left\":"<<small<<",\"sorted_transposed_left\":"<<large<<",\"labeled_graphs\":"<<want<<",\"original_orbits\":"<<a.items<<",\"transposed_orbits\":"<<b.items<<",\"h_checksum\":"<<arr(a.h)<<",\"matches_transposed\":true,\"source_sha256\":\""<<c.sha<<"\",\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/("gate-transpose-n"+std::to_string(n)+".json"),o.str());}
static std::vector<std::pair<int,int>> sample(const std::string&n){std::vector<std::pair<int,int>>e;if(n=="P11")for(int i=0;i<10;++i)e.emplace_back(i,i+1);else if(n=="K23-tail11"){for(int x=0;x<2;++x)for(int y=2;y<5;++y)e.emplace_back(x,y);e.insert(e.end(),{{2,5},{5,6},{6,7},{7,8},{8,9},{9,10}});}else if(n=="C6-tail11"){for(int i=0;i<6;++i)e.emplace_back(i,(i+1)%6);e.insert(e.end(),{{0,6},{6,7},{7,8},{8,9},{9,10}});}else throw std::runtime_error("unknown sample");return e;}
static std::vector<int> fromedges(const std::vector<std::pair<int,int>>&e){std::vector<int>a(11);for(auto[x,y]:e){a[x]|=1<<y;a[y]|=1<<x;}return a;}
static void gate11(const Cfg&c){std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-n11-direct\",\"source_sha256\":\""<<c.sha<<"\",\"samples\":[";bool first=true;for(const std::string n:{"P11","K23-tail11","C6-tail11"}){auto a=fromedges(sample(n));auto h=hist(a,bysize(11));auto d=direct(a);if(h!=d||rj7(h))throw std::runtime_error("N11 direct gate fails "+n);if(!first)o<<",";first=false;o<<"{\"name\":\""<<n<<"\",\"h\":"<<arr(h)<<",\"Rj7\":0,\"dp_equals_direct\":true}";}o<<"],\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/"gate-n11-direct.json",o.str());}
static std::vector<int> transpose_mask_adj(int small,U64 mask){int right=11-small;std::vector<int>rows(right);for(int x=0;x<small;++x)for(int j=0;j<right;++j)if((mask>>(x*right+j))&1ULL)rows[j]|=1<<x;return rowadj(11,right,rows);}
static void gate11_transpose(const Cfg&c){std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-n11-transpose\",\"source_sha256\":\""<<c.sha<<"\",\"samples\":[";bool first=true;for(const auto [small,mask]:std::vector<std::pair<int,U64>>{{4,0x0f3a5c7ULL},{4,0x055aa55ULL},{5,0x12345678ULL},{5,0x0a55aa55ULL}}){auto a=edgeadj(11,pairs(11,small),mask);auto b=transpose_mask_adj(small,mask);auto h=hist(a,bysize(11));auto t=hist(b,bysize(11));if(h!=t||rj7(h))throw std::runtime_error("N11 transpose per-h gate fails");if(!first)o<<",";first=false;o<<"{\"original_small_left\":"<<small<<",\"transposed_left\":"<<(11-small)<<",\"edge_mask\":"<<mask<<",\"h\":"<<arr(h)<<",\"Rj7\":0,\"h_matches\":true}";}o<<"],\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/"gate-n11-transpose.json",o.str());}
static void gate_tail_ranks(const Cfg&c){std::ostringstream o;o<<"{\"status\":\"passed\",\"mode\":\"gate-n11-large-side-tail-ranks\",\"source_sha256\":\""<<c.sha<<"\",\"samples\":[";bool first=true;for(int left:{7,6}){int m=1<<(11-left);U64 tot=binom(m+left-1,left);for(U64 rank=tot-8;rank<tot;++rank){auto rows=unrank(m,left,rank);auto h=hist(rowadj(11,left,rows),bysize(11));if(rj7(h))throw std::runtime_error("tail rank nonzero Rj7");if(!first)o<<",";first=false;o<<"{\"sorted_transposed_left\":"<<left<<",\"original_small_left\":"<<(11-left)<<",\"orbit_rank\":"<<rank<<",\"row_masks\":"<<rowsj(rows)<<",\"h\":"<<arr(h)<<",\"Rj7\":0}";}}o<<"],\"utc\":\""<<utc()<<"\"}";put(fs::path(c.out)/"gate-n11-large-side-tail-ranks.json",o.str());}
static std::string shardj(const Cfg&c,const std::string&s,U64 next,U64 seen,U64 wg,I64 mx,const std::optional<std::string>&ce=std::nullopt){std::ostringstream o;o<<"{\"status\":\""<<s<<"\",\"mode\":\"scan-roworbit-j7\",\"N\":11,\"left_size\":"<<c.left<<",\"orbit_start\":"<<c.start<<",\"orbit_stop_exclusive\":"<<c.stop<<",\"next_orbit_rank\":"<<next<<",\"orbits_scanned\":"<<seen<<",\"weighted_labeled_graphs\":"<<wg<<",\"max_abs_Rj7\":"<<mx<<",\"shard_id\":\""<<c.shard<<"\",\"source_sha256\":\""<<c.sha<<"\",\"utc\":\""<<utc()<<"\"";if(ce)o<<",\"counterexample\":"<<*ce;return o<<"}",o.str();}
static void scan(const Cfg&c){if(c.left<1||c.left>10||c.shard.empty()||!c.stop||!c.every)throw std::runtime_error("bad scan arguments");int m=1<<(11-c.left);U64 tot=binom(m+c.left-1,c.left);if(c.start>c.stop||c.stop>tot)throw std::runtime_error("bad scan range");auto p=fs::path(c.out)/("roworbit-l"+std::to_string(c.left)+"-"+c.shard+".json");if(fs::exists(p))throw std::runtime_error("refusing checkpoint overwrite");auto bs=bysize(11);U64 seen=0,wg=0;I64 mx=0;put(p,shardj(c,"running",c.start,0,0,0));for(U64 k=c.start;k<c.stop;++k){auto x=unrank(m,c.left,k);U64 w=weight(x);auto h=hist(rowadj(11,c.left,x),bs);I64 z=rj7(h);++seen;wg+=w;mx=std::max(mx,z<0?-z:z);if(z){std::ostringstream ce;ce<<"{\"orbit_rank\":"<<k<<",\"row_masks\":"<<rowsj(x)<<",\"coverage_weight\":"<<w<<",\"h\":"<<arr(h)<<",\"Rj7\":"<<z<<"}";put(p,shardj(c,"counterexample",k+1,seen,wg,mx,ce.str()));std::exit(3);}if(seen%c.every==0)put(p,shardj(c,"running",k+1,seen,wg,mx));}put(p,shardj(c,"completed",c.stop,seen,wg,mx));}
int main(int ac,char**av){try{auto c=parse(ac,av);if(c.mode=="gate-roworbit-n7")gate(c,7,r45,"R45=h3-3h4+2h5");else if(c.mode=="gate-roworbit-n9")gate(c,9,r27,"R27=h2-5h4+5h6-2h7");else if(c.mode=="gate-roworbit-n9-l1")gate_part(c,9,1,r27,"R27=h2-5h4+5h6-2h7");else if(c.mode=="gate-roworbit-n9-l2")gate_part(c,9,2,r27,"R27=h2-5h4+5h6-2h7");else if(c.mode=="gate-transpose-n7")gate_transpose(c,7,3,4,r45,"R45=h3-3h4+2h5");else if(c.mode=="gate-transpose-n9")gate_transpose(c,9,4,5,r27,"R27=h2-5h4+5h6-2h7");else if(c.mode=="gate-n11-direct")gate11(c);else if(c.mode=="gate-n11-transpose")gate11_transpose(c);else if(c.mode=="gate-n11-large-side-tail-ranks")gate_tail_ranks(c);else if(c.mode=="scan-roworbit-j7")scan(c);else throw std::runtime_error("unknown mode");return 0;}catch(const std::exception&e){std::cerr<<"fatal: "<<e.what()<<"\n";return 2;}}
